28: pub fn encrypt_backup(data: &[u8], passphrase: &str) -> Result<String> {
29:     if passphrase.is_empty() {
30:         bail!("Passphrase cannot be empty");
31:     }
32: 
33:     let mut salt = [0u8; 16];
34:     let mut nonce_bytes = [0u8; 12];
35:     rand::fill(&mut salt);
36:     rand::fill(&mut nonce_bytes);
37: 
38:     let mut key = [0u8; 32];
39:     let argon2 = Argon2::default();
40:     argon2
41:         .hash_password_into(passphrase.as_bytes(), &salt, &mut key)
42:         .map_err(|e| anyhow!("Argon2 key derivation failed: {e}"))?;
43: 
44:     let cipher = Aes256Gcm::new_from_slice(&key)
45:         .map_err(|e| anyhow!("Failed initializing AES-256-GCM cipher: {e}"))?;
46:     let nonce = Nonce::from(nonce_bytes);
47:     let ciphertext_bytes = cipher
48:         .encrypt(&nonce, data)
49:         .map_err(|e| anyhow!("Encryption failed: {e}"))?;
50: 
51:     let backup = EncryptedBackup {
52:         version: 1,
53:         kdf: "argon2id".to_string(),
54:         cipher: "aes-256-gcm".to_string(),
55:         salt: Base64::encode_string(&salt),
56:         nonce: Base64::encode_string(&nonce_bytes),
57:         ciphertext: Base64::encode_string(&ciphertext_bytes),
58:     };
59: 
60:     Ok(serde_json::to_string_pretty(&backup)?)
61: }
