63: pub fn decrypt_backup(json_str: &str, passphrase: &str) -> Result<Vec<u8>> {
64:     let backup: EncryptedBackup =
65:         serde_json::from_str(json_str.trim()).context("Invalid encrypted backup structure")?;
66: 
67:     if backup.version != 1 {
68:         bail!("Unsupported backup version: {}", backup.version);
69:     }
70:     if backup.kdf != "argon2id" {
71:         bail!("Unsupported KDF algorithm: {}", backup.kdf);
72:     }
73:     if backup.cipher != "aes-256-gcm" {
74:         bail!("Unsupported cipher: {}", backup.cipher);
75:     }
76: 
77:     let salt =
78:         Base64::decode_vec(&backup.salt).map_err(|e| anyhow!("Failed decoding salt: {e}"))?;
79:     let nonce_bytes =
80:         Base64::decode_vec(&backup.nonce).map_err(|e| anyhow!("Failed decoding nonce: {e}"))?;
81:     let ciphertext = Base64::decode_vec(&backup.ciphertext)
82:         .map_err(|e| anyhow!("Failed decoding ciphertext: {e}"))?;
83: 
84:     if nonce_bytes.len() != 12 {
85:         bail!("Invalid nonce length (expected 12 bytes)");
86:     }
87: 
88:     let mut key = [0u8; 32];
89:     let argon2 = Argon2::default();
90:     argon2
91:         .hash_password_into(passphrase.as_bytes(), &salt, &mut key)
92:         .map_err(|e| anyhow!("Argon2 key derivation failed: {e}"))?;
93: 
94:     let cipher = Aes256Gcm::new_from_slice(&key)
95:         .map_err(|e| anyhow!("Failed initializing AES-256-GCM cipher: {e}"))?;
96:     let nonce =
97:         Nonce::try_from(nonce_bytes.as_slice()).map_err(|e| anyhow!("Invalid nonce: {e}"))?;
98:     let decrypted = cipher
99:         .decrypt(&nonce, ciphertext.as_ref())
100:         .map_err(|_| anyhow!("Decryption failed: incorrect passphrase or corrupted data"))?;
101: 
102:     Ok(decrypted)
103: }
