64: impl ConfigFile {
65:     /// Parse configuration file content given a format.
66:     pub fn parse(content: &str, format: ConfigFormat) -> Result<Self> {
67:         match format {
68:             ConfigFormat::Toml => {
69:                 toml::from_str(content).context("Failed to parse TOML configuration")
70:             }
71:             ConfigFormat::Yaml => {
72:                 serde_yaml_ng::from_str(content).context("Failed to parse YAML configuration")
73:             }
74:             ConfigFormat::Json => {
75:                 serde_json::from_str(content).context("Failed to parse JSON configuration")
76:             }
77:         }
78:     }
79: 
80:     /// Load and parse a configuration file from a specified path.
81:     pub fn load_from_path(path: &Path) -> Result<Self> {
82:         let content = fs::read_to_string(path)
83:             .with_context(|| format!("Failed to read configuration file '{}'", path.display()))?;
84: 
85:         let format = ConfigFormat::from_path(path).ok_or_else(|| {
86:             anyhow::anyhow!(
87:                 "Unsupported configuration format for '{}'. Expected .toml, .yaml, .yml, or .json",
88:                 path.display()
89:             )
90:         })?;
91: 
92:         Self::parse(&content, format)
93:     }
94: 
95:     /// Discover and load the default configuration file if present at standard paths.
96:     pub fn load_default() -> Result<Option<(PathBuf, Self)>> {
97:         for path in default_config_paths() {
98:             if path.is_file() {
99:                 let cfg = Self::load_from_path(&path)?;
100:                 return Ok(Some((path, cfg)));
101:             }
102:         }
103:         Ok(None)
104:     }
