106:     /// Save configuration file back to disk in its corresponding format.
107:     pub fn save_to_path(&self, path: &Path) -> Result<()> {
108:         if let Some(parent) = path.parent() {
109:             fs::create_dir_all(parent)?;
110:         }
111:         let format = ConfigFormat::from_path(path).ok_or_else(|| {
112:             anyhow::anyhow!(
113:                 "Unsupported configuration format for '{}'. Expected .toml, .yaml, .yml, or .json",
114:                 path.display()
115:             )
116:         })?;
117: 
118:         let text = match format {
119:             ConfigFormat::Toml => {
120:                 toml::to_string_pretty(self).context("Failed serializing TOML")?
121:             }
122:             ConfigFormat::Yaml => {
123:                 serde_yaml_ng::to_string(self).context("Failed serializing YAML")?
124:             }
125:             ConfigFormat::Json => {
126:                 serde_json::to_string_pretty(self).context("Failed serializing JSON")?
127:             }
128:         };
129: 
130:         fs::write(path, text)?;
131:         Ok(())
132:     }
