134:     /// Set default namespace in the configuration file and persist it.
135:     pub fn set_default_namespace_in_file(
136:         path: Option<&Path>,
137:         new_default: &str,
138:     ) -> Result<PathBuf> {
139:         let (target_path, mut config) = if let Some(p) = path {
140:             let cfg = if p.is_file() {
141:                 Self::load_from_path(p)?
142:             } else {
143:                 Self::default()
144:             };
145:             (p.to_path_buf(), cfg)
146:         } else if let Some((p, cfg)) = Self::load_default()? {
147:             (p, cfg)
148:         } else {
149:             let default_paths = default_config_paths();
150:             let first = default_paths.into_iter().next().ok_or_else(|| {
151:                 anyhow::anyhow!("Unable to determine default config file location")
152:             })?;
153:             (first, Self::default())
154:         };
155: 
156:         config.default_namespace = Some(new_default.to_string());
157:         config.save_to_path(&target_path)?;
158:         Ok(target_path)
159:     }
