313: /// Resolves configuration taking into account:
314: /// 1. Explicit CLI arguments (if passed)
315: /// 2. Environment variables (`TFA_STORAGE`, `TFA_CLIPBOARD`, `TFA_CLIP_COMMAND`, `TFA_NAMESPACE`, `TFA_DIGITS`, `TFA_PERIOD`, `TFA_ALGORITHM`, `TFA_AUTO_COPY`, `TFA_LIGHT`)
316: /// 3. Configuration file (either explicit path via `--config` / `TFA_CONFIG`, or discovered default in `~/.config/tfa/config.*`)
317: /// 4. Hardcoded defaults
318: pub fn resolve_configuration(
319:     cli_config_path: Option<&Path>,
320:     cli_storage: Option<StorageBackend>,
321:     cli_clipboard: Option<ClipboardProvider>,
322:     cli_clip_command: Option<String>,
323:     cli_namespace: Option<String>,
324: ) -> Result<(ResolvedConfig, Option<ConfigFile>)> {
325:     // Determine config file path: explicit CLI / TFA_CONFIG or default discovery
326:     let config_file = if let Some(path) = cli_config_path {
327:         if path.is_file() {
328:             Some(ConfigFile::load_from_path(path)?)
329:         } else if path.exists() {
330:             anyhow::bail!(
331:                 "Configuration path '{}' is not a regular file",
332:                 path.display()
333:             );
334:         } else {
335:             None
336:         }
337:     } else if let Ok(env_path) = std::env::var("TFA_CONFIG") {
338:         if !env_path.trim().is_empty() {
339:             let p = Path::new(&env_path);
340:             if p.is_file() {
341:                 Some(ConfigFile::load_from_path(p)?)
342:             } else if p.exists() {
343:                 anyhow::bail!("Configuration path '{}' is not a regular file", p.display());
344:             } else {
345:                 None
