10: /// Parse import payload from string (migration URL, OTPAuth URLs, or JSON export)
11: pub fn parse_import_payload(input: &str) -> Result<Vec<ImportItem>> {
12:     let trimmed = input.trim();
13: 
14:     if trimmed.is_empty() {
15:         bail!("Import payload is empty");
16:     }
17: 
18:     // 1. Google Authenticator migration payload
19:     if trimmed.starts_with("otpauth-migration://") {
20:         return parse_google_migration(trimmed);
21:     }
22: 
23:     // 2. Try JSON (tfa export, Bitwarden, Aegis, key-value map)
24:     if (trimmed.starts_with('{') && trimmed.ends_with('}'))
25:         || (trimmed.starts_with('[') && trimmed.ends_with(']'))
26:     {
27:         if let Ok(items) = parse_json_export(trimmed) {
28:             if !items.is_empty() {
29:                 return Ok(items);
30:             }
31:         }
32:     }
33: 
34:     // 3. Line-separated otpauth:// or otpauth-migration:// URIs
35:     let mut items = Vec::new();
36:     for line in trimmed.lines() {
37:         let line = line.trim();
38:         if line.is_empty() || line.starts_with('#') {
39:             continue;
40:         }
41: 
42:         if line.starts_with("otpauth-migration://") {
43:             let mut mig_items = parse_google_migration(line)?;
44:             items.append(&mut mig_items);
45:         } else if line.starts_with("otpauth://") {
46:             let account = extract_account_from_otpauth(line);
47:             items.push(ImportItem {
48:                 account,
49:                 secret: line.to_string(),
50:             });
51:         }
52:     }
53: 
54:     if items.is_empty() {
55:         bail!("Could not identify valid 2FA secrets or accounts in import payload");
56:     }
57: 
58:     Ok(items)
59: }
