62:     let accounts = google_authenticator_converter::process_data(uri)
63:         .map_err(|e| anyhow::anyhow!("Failed parsing Google Authenticator migration URL: {e}"))?;
64: 
65:     let items = accounts
66:         .into_iter()
67:         .map(|acc| {
68:             let account_name = if acc.name.is_empty() {
69:                 acc.issuer
70:             } else {
71:                 acc.name
