174:         let path = url.path().trim_start_matches('/');
175:         if let Some(acc) = path.split(':').next_back() {
176:             if !acc.is_empty() {
177:                 return acc.to_string();
178:             }
179:         }
180:         if !path.is_empty() {
181:             return path.to_string();
182:         }
183:     }
184:     "imported_account".to_string()
185: }
