224: impl AccountStore for KeyringStore {
225:     fn set_secret(&self, account: &str, secret: &str) -> Result<()> {
226:         let entry = keyring::Entry::new(&self.service, account)?;
227:         entry
228:             .set_password(secret)
229:             .map_err(|e| anyhow::anyhow!("Failed saving secret in keyring: {e}"))?;
230: 
231:         let mut index = self.get_index()?;
232:         if !index.contains(&account.to_string()) {
233:             index.push(account.to_string());
234:             index.sort();
235:             self.save_index(&index)?;
236:         }
237:         Ok(())
238:     }
239: 
240:     fn get_secret(&self, account: &str) -> Result<String> {
241:         let entry = keyring::Entry::new(&self.service, account)?;
242:         match entry.get_password() {
243:             Ok(secret) => Ok(secret),
244:             Err(keyring::Error::NoEntry) => bail!("Account '{account}' not found in keyring"),
245:             Err(e) => Err(anyhow::anyhow!("Failed reading secret from keyring: {e}")),
246:         }
247:     }
