336: /// Parses raw wire-format bytes and optional comment from an OpenSSH public key line.
337: fn parse_ssh_pubkey_info(line: &str) -> Option<(Vec<u8>, Option<String>)> {
338:     let parts: Vec<&str> = line.split_whitespace().collect();
339:     if parts.len() >= 2 {
340:         if let Ok(raw_bytes) = Base64::decode_vec(parts[1]) {
341:             let comment = if parts.len() > 2 {
342:                 Some(parts[2..].join(" "))
343:             } else {
344:                 None
345:             };
346:             return Some((raw_bytes, comment));
347:         }
348:     }
349:     None
350: }
