352: /// Matches a candidate SSH key against an expected fingerprint, comment, or identifier.
353: fn ssh_fingerprint_matches(
354:     expected: &str,
355:     raw_pubkey: &[u8],
356:     comment: Option<&str>,
357:     key_path: Option<&Path>,
358: ) -> bool {
359:     let expected = expected.trim();
360:     if expected.is_empty() {
361:         return true;
362:     }
363: 
364:     if let Some(c) = comment {
365:         if c.trim().eq_ignore_ascii_case(expected) {
366:             return true;
367:         }
368:     }
369: 
370:     if let Some(p) = key_path {
371:         if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
372:             if name.eq_ignore_ascii_case(expected)
373:                 || name.trim_end_matches(".pub").eq_ignore_ascii_case(expected)
374:             {
375:                 return true;
376:             }
377:         }
378:     }
379: 
380:     let digest = Sha256::digest(raw_pubkey);
381:     let b64_padded = Base64::encode_string(&digest);
382:     let b64_unpadded = b64_padded.trim_end_matches('=');
383:     let openssh_fp = format!("SHA256:{b64_unpadded}");
384:     let openssh_fp_padded = format!("SHA256:{b64_padded}");
385:     let hex_fp = digest
386:         .iter()
387:         .map(|b| format!("{b:02x}"))
388:         .collect::<String>();
389:     let hex_colon_fp = digest
390:         .iter()
391:         .map(|b| format!("{b:02x}"))
392:         .collect::<Vec<_>>()
393:         .join(":");
394: 
395:     if expected.eq_ignore_ascii_case(&openssh_fp)
396:         || expected.eq_ignore_ascii_case(&openssh_fp_padded)
397:         || expected.eq_ignore_ascii_case(b64_unpadded)
398:         || expected.eq_ignore_ascii_case(&b64_padded)
399:         || expected.eq_ignore_ascii_case(&hex_fp)
400:         || expected.eq_ignore_ascii_case(&hex_colon_fp)

